16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "membership_number")
60	    private Integer membershipNumber;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
66	    private Set<Pet> pets;
67	
68	    public String getAddress() {
69	        return this.address;
70	    }
71	
72	    public void setAddress(String address) {
73	        this.address = address;
74	    }
75	
76	    public String getCity() {
77	        return this.city;
78	    }
79	
80	    public void setCity(String city) {
81	        this.city = city;
82	    }
83	
84	    public String getTelephone() {
85	        return this.telephone;
86	    }
87	
88	    /**
89	     * Store the telephone number as digits only, stripping any spaces, dashes
90	     * and parentheses so that, e.g., "(613) 555-0100" and "6135550100" are kept
91	     * as the same value.
92	     */
93	    public void setTelephone(String telephone) {
94	        this.telephone = telephone == null ? null : telephone.replaceAll("[^0-9]", "");
95	    }
96	
97	    public String getEmail() {
98	        return this.email;
99	    }
100	
101	    public void setEmail(String email) {
102	        this.email = email;
103	    }
104	
105	    public LocalDate getRegistrationDate() {
106	        return this.registrationDate;
107	    }
108	
109	    public void setRegistrationDate(LocalDate registrationDate) {
110	        this.registrationDate = registrationDate;
111	    }
112	
113	    public Integer getMembershipNumber() {
114	        return this.membershipNumber;
115	    }
116	
117	    public void setMembershipNumber(Integer membershipNumber) {
118	        this.membershipNumber = membershipNumber;
119	    }
120	
121	    public String getCustomerCode() {
122	        return this.customerCode;
123	    }
124	
125	    public void setCustomerCode(String customerCode) {
126	        this.customerCode = customerCode;
127	    }
128	
129	    /**
130	     * The owner's display name, formatted as 'LastName, FirstName'.
131	     */
132	    @Transient
133	    public String getDisplayName() {
134	        return this.getLastName() + ", " + this.getFirstName();
135	    }
136	
137	    /**
138	     * The owner's initials: the upper-cased first letters of the first and last
139	     * name, dot-separated with a trailing dot, e.g. 'J.S.'.
140	     */
141	    @Transient
142	    public String getInitials() {
143	        return (this.getFirstName().substring(0, 1) + "." + this.getLastName().substring(0, 1) + ".")
144	            .toUpperCase();
145	    }
146	
147	    protected Set<Pet> getPetsInternal() {
148	        if (this.pets == null) {
149	            this.pets = new HashSet<>();
150	        }
151	        return this.pets;
152	    }
153	
154	    protected void setPetsInternal(Set<Pet> pets) {
155	        this.pets = pets;
156	    }
157	
158	    public List<Pet> getPets() {
159	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
160	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
161	        return Collections.unmodifiableList(sortedPets);
162	    }
163	
164	    public void setPets(List<Pet> pets) {
165	        this.pets = new HashSet<>(pets);
166	    }
167	
168	    public void addPet(Pet pet) {
169	        getPetsInternal().add(pet);
170	        pet.setOwner(this);
171	    }
172	
173	    /**
174	     * Return the Pet with the given name, or null if none found for this Owner.
175	     *
176	     * @param name to test
177	     * @return true if pet name is already in use
178	     */
179	    public Pet getPet(String name) {
180	        return getPet(name, false);
181	    }
182	
183	    /**
184	     * Return the Pet with the given name, or null if none found for this Owner.
185	     *
186	     * @param name to test
187	     * @return true if pet name is already in use
188	     */
189	    public Pet getPet(String name, boolean ignoreNew) {
190	        name = name.toLowerCase();
191	        for (Pet pet : getPetsInternal()) {
192	            if (!ignoreNew || !pet.isNew()) {
193	                String compName = pet.getName();
194	                compName = compName.toLowerCase();
195	                if (compName.equals(name)) {
196	                    return pet;
197	                }
198	            }
199	        }
200	        return null;
201	    }
202	
203	    public Pet getPet(Integer petId) {
204	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
205	    }
206	
207	    @Override
208	    public String toString() {
209	        return new ToStringCreator(this)
210	
211	            .append("id", this.getId())
212	            .append("new", this.isNew())
213	            .append("lastName", this.getLastName())
214	            .append("firstName", this.getFirstName())
215	            .append("address", this.address)
216	            .append("city", this.city)
217	            .append("telephone", this.telephone)
218	            .append("email", this.email)
219	            .toString();
220	    }
221	}
