273	    private boolean isDuplicateTelephone(Owner owner) {
274	        String telephone = normalizeTelephone(owner.getTelephone());
275	        return ownerRepository.findAll().stream()
276	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
277	                && Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
278	    }
279	
280	    /**
281	     * Normalize a telephone number for duplicate detection by stripping every
282	     * character that is not a digit (spaces, dashes and parentheses), so that
283	     * "(613) 555-0100" and "6135550100" are treated as the same number. A
284	     * {@code null} value stays {@code null}.
285	     */
286	    private static String normalizeTelephone(String value) {
287	        if (value == null) {
288	            return null;
289	        }
290	        return value.replaceAll("[^0-9]", "");
291	    }
292	
293	    private boolean isDuplicateEmail(Owner owner) {
294	        String email = owner.getEmail();
295	        if (email == null || email.isBlank()) {
296	            return false;
297	        }
298	        String normalizedEmail = normalize(email);
299	        return ownerRepository.findAll().stream()
300	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
301	                && Objects.equals(normalize(existing.getEmail()), normalizedEmail));
302	    }
303	
304	    /**
305	     * Normalize a textual value for duplicate detection so that comparisons
306	     * ignore letter case and surrounding or repeated whitespace. A {@code null}
307	     * value stays {@code null}; otherwise surrounding whitespace is trimmed, any
308	     * run of internal whitespace is collapsed to a single space, and letters are
309	     * lower-cased. For example "  john   smith " and "John Smith" normalize to
310	     * the same value and therefore count as the same person.
311	     */
312	    private static String normalize(String value) {
313	        if (value == null) {
314	            return null;
315	        }
316	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
317	    }
