280	    /**
281	     * Normalize a telephone number for duplicate detection by stripping every
282	     * character that is not a digit (spaces, dashes and parentheses), so that
283	     * "(613) 555-0100" and "6135550100" are treated as the same number. A
284	     * {@code null} value stays {@code null}.
285	     */
286	    private static String normalizeTelephone(String value) {
287	        if (value == null) {
288	            return null;
289	        }
290	        return value.replaceAll("[^0-9]", "");
291	    }
