293	    private boolean isDuplicateEmail(Owner owner) {
294	        String email = owner.getEmail();
295	        if (email == null || email.isBlank()) {
296	            return false;
297	        }
298	        String normalizedEmail = normalize(email);
299	        return ownerRepository.findAll().stream()
300	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
301	                && Objects.equals(normalize(existing.getEmail()), normalizedEmail));
302	    }
